fn ndAccelKeyName(k: []const u8) []const u8 {
    if (std.mem.eql(u8, k, "enter")) return "Return";
    if (std.mem.eql(u8, k, "escape")) return "Escape";
    if (std.mem.eql(u8, k, "backspace")) return "BackSpace";
    if (std.mem.eql(u8, k, "delete")) return "Delete";
    if (std.mem.eql(u8, k, "space")) return "space";
    if (std.mem.eql(u8, k, "tab")) return "Tab";
    if (std.mem.eql(u8, k, "left")) return "Left";
    if (std.mem.eql(u8, k, "right")) return "Right";
    if (std.mem.eql(u8, k, "up")) return "Up";
    if (std.mem.eql(u8, k, "down")) return "Down";
    if (std.mem.eql(u8, k, "comma")) return "comma";
    if (std.mem.eql(u8, k, "period")) return "period";
    return k; // single printable char (and f1..f12) pass through verbatim
}

fn ndAccelToGtk(spec: []const u8, dupeZ: *const fn ([]const u8) [:0]const u8) ?[:0]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    defer buf.deinit(events_gpa);
    var it = std.mem.splitScalar(u8, spec, '+');
    var key: ?[]const u8 = null;
    while (it.next()) |part| {
        if (std.mem.eql(u8, part, "primary")) buf.appendSlice(events_gpa, "<Primary>") catch return null
        else if (std.mem.eql(u8, part, "shift")) buf.appendSlice(events_gpa, "<Shift>") catch return null
        else if (std.mem.eql(u8, part, "alt")) buf.appendSlice(events_gpa, "<Alt>") catch return null
        else if (std.mem.eql(u8, part, "ctrl")) buf.appendSlice(events_gpa, "<Control>") catch return null
        else key = part;
    }
    const k = key orelse return null;
    buf.appendSlice(events_gpa, ndAccelKeyName(k)) catch return null;
    return dupeZ(buf.items);
}

fn ndMenubarCreate(app: *gtk.Application, window: ?*gtk.Window, defaults: bool) *gtk.Widget {
    menu_app = app;
    menu_window = window;
    const m = gio.Menu.new();
    the_menubar = m;
    menu_defaults = defaults;
    return @ptrCast(@alignCast(m));
}

fn ndMenuCreate(app: *gtk.Application, label: [:0]const u8) *gtk.Widget {
    menu_app = app;
    const m = gio.Menu.new();
    menu_labels.put(events_gpa, @intFromPtr(m), label) catch {};
    return @ptrCast(@alignCast(m));
}

fn ndMenuItemCreate(app: *gtk.Application, props: ?std.json.Value, dupeZ: *const fn ([]const u8) [:0]const u8) *gtk.Widget {
    menu_app = app;
    const item = gio.MenuItem.new(null, null);
    var info = MenuItemInfo{};
    info.label = dupeZ(propStr(props, "label") orelse "");
    if (propStr(props, "iconName")) |ic| info.icon = dupeZ(ic);
    if (propStr(props, "accelerator")) |ac| info.accel = ndAccelToGtk(ac, dupeZ);
    info.role = parseMenuRole(propStr(props, "role") orelse "none");
    info.enabled = propBool(props, "enabled") orelse true;
    menu_item_info.put(events_gpa, @intFromPtr(item), info) catch {};
    return @ptrCast(@alignCast(item));
}

fn cbMenuActionActivate(_: *gobject.Object, _: ?*glib.Variant, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "selected", .{});
}

fn cbMenuAboutActivate(_: *gobject.Object, _: ?*glib.Variant, _: ?*anyopaque) callconv(.c) void {
    const dialog = adw.AboutDialog.new();
    if (menu_window) |w| {
        const title = gtk.Window.getTitle(w);
        if (title) |t| adw.AboutDialog.setApplicationName(dialog, t);
    }
    adw.Dialog.present(dialog.as(adw.Dialog), if (menu_window) |w| w.as(gtk.Widget) else null);
}

fn ndMenuEnsureAbout() void {
    if (menu_about_added) return;
    const app = menu_app orelse return;
    const sa = gio.SimpleAction.new("nd-about", null);
    _ = gobject.signalConnectData(@ptrCast(@alignCast(sa)), "activate", @ptrCast(&cbMenuAboutActivate), null, null, .{});
    gio.ActionMap.addAction(app.as(gio.ActionMap), sa.as(gio.Action));
    menu_about_added = true;
}

pub fn ndMenuItemConnect(item_w: *gtk.Widget, node_id: u32) void {
    const item: *gio.MenuItem = @ptrCast(@alignCast(item_w));
    const info = menu_item_info.getPtr(@intFromPtr(item)) orelse return;
    info.node_id = node_id;
    menu_node_ids.put(events_gpa, node_id, @intFromPtr(item)) catch {};
    if (info.role != .none and info.role != .settings) return;
    const app = menu_app orelse return;
    const name = std.fmt.allocPrintSentinel(events_gpa, "nd-menu-{d}", .{node_id}, 0) catch return;
    const sa = gio.SimpleAction.new(name, null);
    info.action = sa;
    _ = gobject.signalConnectData(@ptrCast(@alignCast(sa)), "activate", @ptrCast(&cbMenuActionActivate), @ptrFromInt(@as(usize, node_id)), null, .{});
    gio.SimpleAction.setEnabled(sa, @intFromBool(info.enabled));
    gio.ActionMap.addAction(app.as(gio.ActionMap), sa.as(gio.Action));
    if (info.accel) |accel| {
        const detailed = std.fmt.allocPrintSentinel(events_gpa, "app.nd-menu-{d}", .{node_id}, 0) catch return;
        var accels = [_]?[*:0]const u8{ accel.ptr, null };
        gtk.Application.setAccelsForAction(app, detailed, @ptrCast(&accels));
    }
}

fn ndMenuItemSetEnabled(item_w: *gtk.Widget, enabled: bool) void {
    const item: *gio.MenuItem = @ptrCast(@alignCast(item_w));
    const info = menu_item_info.getPtr(@intFromPtr(item)) orelse return;
    info.enabled = enabled;
    if (info.action) |sa| gio.SimpleAction.setEnabled(sa, @intFromBool(enabled));
}

fn ndBuildGMenuItem(info: MenuItemInfo) ?*gio.MenuItem {
    switch (info.role) {
        .separator, .dropped => return null,
        .about => {
            const lbl: [*:0]const u8 = if (info.label.len > 0) info.label.ptr else "About";
            return gio.MenuItem.new(lbl, "app.nd-about");
        },
        .none, .settings => {
            const lbl: [*:0]const u8 = if (info.label.len > 0) info.label.ptr else (if (info.role == .settings) "Preferences" else "");
            const detailed = std.fmt.allocPrintSentinel(events_gpa, "app.nd-menu-{d}", .{info.node_id}, 0) catch return null;
            return gio.MenuItem.new(lbl, detailed);
        },
    }
}

fn ndBuildSubmenuModel(submenu: *gio.Menu) ?*gio.Menu {
    const items = submenu_items.get(@intFromPtr(submenu)) orelse return null;
    const root = gio.Menu.new();
    var section = gio.Menu.new();
    var any = false;
    for (items.items) |item_ptr| {
        const info = menu_item_info.get(item_ptr) orelse continue;
        if (info.role == .separator) {
            gio.Menu.appendSection(root, null, section.as(gio.MenuModel));
            section = gio.Menu.new();
            continue;
        }
        if (ndBuildGMenuItem(info)) |gi| {
            gio.Menu.appendItem(section, gi);
            any = true;
        }
    }
    gio.Menu.appendSection(root, null, section.as(gio.MenuModel));
    return if (any) root else null;
}

fn ndBuildMenubarModel() ?*gio.Menu {
    const menubar = the_menubar orelse return null;
    const menus = menubar_menus.get(@intFromPtr(menubar)) orelse return null;
    const root = gio.Menu.new();
    var any = false;
    for (menus.items) |submenu_ptr| {
        const submenu: *gio.Menu = @ptrFromInt(submenu_ptr);
        if (ndBuildSubmenuModel(submenu)) |model| {
            const label = menu_labels.get(submenu_ptr) orelse "";
            const lbl: [*:0]const u8 = if (label.len > 0) label.ptr else "Menu";
            gio.Menu.appendSubmenu(root, lbl, model.as(gio.MenuModel));
            any = true;
        }
    }
    return if (any) root else null;
}

fn ndMenuRefresh() void {
    const app = menu_app orelse return;
    if (the_menubar == null) return;
    ndMenuEnsureAbout();
    const model = ndBuildMenubarModel() orelse return;
    if (menu_headerbars.items.len > 0) {
        const target = menu_headerbars.items[menu_headerbars.items.len - 1];
        if (menu_primary_button == null) {
            const btn = gtk.MenuButton.new();
            // Own a strong ref (sinks the floating ref): rehoming does
            // HeaderBar.remove -> packEnd, and remove() would otherwise drop
            // the last ref and destroy the button mid-rehome (observed as
            // GTK_IS_WIDGET / GTK_IS_MENU_BUTTON criticals with 2+ headerbars).
            _ = gobject.Object.refSink(btn.as(gobject.Object));
            gtk.MenuButton.setIconName(btn, "open-menu-symbolic");
            gtk.Widget.setTooltipText(btn.as(gtk.Widget), "Main Menu");
            menu_primary_button = btn;
        }
        const btn = menu_primary_button.?;
        gtk.MenuButton.setMenuModel(btn, model.as(gio.MenuModel));
        if (menu_primary_parent != target) {
            if (menu_primary_parent) |old| adw.HeaderBar.remove(old, btn.as(gtk.Widget));
            adw.HeaderBar.packEnd(target, btn.as(gtk.Widget));
            menu_primary_parent = target;
        }
    } else {
        gtk.Application.setMenubar(app, model.as(gio.MenuModel));
    }
}

fn ndMenubarAppendMenu(menubar_w: *gtk.Widget, menu_w: *gtk.Widget) void {
    const menubar: *gio.Menu = @ptrCast(@alignCast(menubar_w));
    const gop = menubar_menus.getOrPut(events_gpa, @intFromPtr(menubar)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(menu_w)) catch {};
    ndMenuRefresh();
}

fn ndMenuAppendItem(menu_w: *gtk.Widget, item_w: *gtk.Widget) void {
    const submenu: *gio.Menu = @ptrCast(@alignCast(menu_w));
    const gop = submenu_items.getOrPut(events_gpa, @intFromPtr(submenu)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(item_w)) catch {};
    ndMenuRefresh();
}

/// Records a headerbar so a later menubar can home its primary button in the
/// LAST one (GNOME convention: the content pane's header). No-op for menu-less
/// apps beyond the record — the button is only created/moved once a <menubar>
/// exists, so counter/gallery/two-pane trees are behaviorally unchanged.
pub fn ndMenuNoteHeaderBar(hb: *adw.HeaderBar) void {
    menu_headerbars.append(events_gpa, hb) catch {};
    if (the_menubar != null) ndMenuRefresh();
}

/// Called from the Window structural arm when a non-widget child (the menubar
/// GMenu) is appended: install the primary menu instead of setting it as the
/// window content.
pub fn ndMenuAttachToWindow(_: *gtk.Widget) void {
    ndMenuRefresh();
}

// ---- <headerbar> back/forward navigation (canGoBack/canGoForward +
// onBack/onForward). The GNOME idiom is two flat GtkButtons packed at the
// AdwHeaderBar START (go-previous-symbolic / go-next-symbolic). Buttons
// materialize when either prop is PRESENT (the app opts in) — a header with no
// nav props gets none. `node_id` (for emitting back/forward) arrives via
// ndHeaderBarConnectNav, decoupled from button creation, so any create/connect
// order works: the click callbacks look the id up by AdwHeaderBar pointer. ----
const HeaderBarNav = struct { back: *gtk.Button, forward: *gtk.Button };
var headerbar_navs: std.AutoHashMapUnmanaged(usize, HeaderBarNav) = .empty; // AdwHeaderBar ptr -> buttons
var headerbar_nav_ids: std.AutoHashMapUnmanaged(usize, u32) = .empty; // AdwHeaderBar ptr -> node id

fn cbHeaderBarBack(_: *gtk.Button, data: ?*anyopaque) callconv(.c) void {
    const id = headerbar_nav_ids.get(@intFromPtr(data)) orelse return;
    if (emit) |f| f(id, "back", .{});
}

fn cbHeaderBarForward(_: *gtk.Button, data: ?*anyopaque) callconv(.c) void {
    const id = headerbar_nav_ids.get(@intFromPtr(data)) orelse return;
    if (emit) |f| f(id, "forward", .{});
}

/// Evict a header's nav entries when it is finalized. A `key`-based remount
/// (the settings example re-keys the content header per page) destroys the old
/// AdwHeaderBar and GLib readily reuses its address for the new one; without
/// this the stale entry's dangling button pointers would reach setSensitive.
fn cbHeaderBarDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    const key = @intFromPtr(w);
    _ = headerbar_navs.remove(key);
    _ = headerbar_nav_ids.remove(key);
}

/// Materializes / updates the header's flat back/forward buttons from the
/// canGoBack/canGoForward props (generated HeaderBar create + applyProps arms).
/// The buttons appear on the first call carrying either flag and persist; each
/// flag only drives its own button's `sensitive`, so a one-sided diffed update
/// can't clobber the other (mirrors the AppKit segmented-control behaviour).
pub fn ndHeaderBarApplyNav(hb: *adw.HeaderBar, can_back: ?bool, can_forward: ?bool) void {
    if (can_back == null and can_forward == null) return; // untouched: not a teardown
    const gop = headerbar_navs.getOrPut(events_gpa, @intFromPtr(hb)) catch return;
    if (!gop.found_existing) {
        const back = gtk.Button.new();
        gtk.Button.setIconName(back, "go-previous-symbolic");
        gtk.Widget.addCssClass(back.as(gtk.Widget), "flat");
        const forward = gtk.Button.new();
        gtk.Button.setIconName(forward, "go-next-symbolic");
        gtk.Widget.addCssClass(forward.as(gtk.Widget), "flat");
        _ = gtk.Button.signals.clicked.connect(back, ?*anyopaque, &cbHeaderBarBack, @ptrCast(hb), .{});
        _ = gtk.Button.signals.clicked.connect(forward, ?*anyopaque, &cbHeaderBarForward, @ptrCast(hb), .{});
        adw.HeaderBar.packStart(hb, back.as(gtk.Widget)); // back leftmost, forward to its right
        adw.HeaderBar.packStart(hb, forward.as(gtk.Widget));
        _ = gtk.Widget.signals.destroy.connect(hb.as(gtk.Widget), ?*anyopaque, &cbHeaderBarDestroyed, null, .{});
        gop.value_ptr.* = .{ .back = back, .forward = forward };
    }
    if (can_back) |b| gtk.Widget.setSensitive(gop.value_ptr.back.as(gtk.Widget), @intFromBool(b));
    if (can_forward) |f| gtk.Widget.setSensitive(gop.value_ptr.forward.as(gtk.Widget), @intFromBool(f));
}

/// Records the header's node id so the back/forward click callbacks can emit
/// (generated connectEvents HeaderBar arm). The buttons' click handlers are
/// wired in ndHeaderBarApplyNav; this only supplies the id they look up.
pub fn ndHeaderBarConnectNav(widget: *gtk.Widget, node_id: u32) void {
    headerbar_nav_ids.put(events_gpa, @intFromPtr(widget), node_id) catch {};
}

/// backend.zig routes a non-widget node handle's semantic click here.
pub fn menuSemanticClick(node_id: u32) bool {
    const item_ptr = menu_node_ids.get(node_id) orelse return false;
    const info = menu_item_info.get(item_ptr) orelse return true;
    switch (info.role) {
        .about => {
            cbMenuAboutActivate(@ptrCast(menu_app orelse return true), null, null);
            return true;
        },
        .separator, .dropped => return true,
        .none, .settings => {
            const app = menu_app orelse return true;
            if (!info.enabled) return true; // disabled: onSelect must not fire
            const name = std.fmt.allocPrintSentinel(events_gpa, "nd-menu-{d}", .{node_id}, 0) catch return true;
            gio.ActionGroup.activateAction(app.as(gio.ActionGroup), name, null);
            return true;
        },
    }
}

/// The GTK create dispatcher. `dupeZ` turns a wire string into a NUL-
/// terminated GTK string using the backend arena (passed by the caller).
pub fn create(
    app: *gtk.Application,
    kind: []const u8,
    props: ?std.json.Value,
    dupeZ: *const fn ([]const u8) [:0]const u8,
    the_window: *?*gtk.Window,
) !*gtk.Widget {
    if (std.mem.eql(u8, kind, "Window")) {
        const window = adw.ApplicationWindow.new(app);
        const win = window.as(gtk.Window);
        the_window.* = win;
        if (propStr(props, "title")) |t| gtk.Window.setTitle(win, dupeZ(t));
        const w: c_int = @intCast(propInt(props, "defaultWidth") orelse 480);
        const h: c_int = @intCast(propInt(props, "defaultHeight") orelse 320);
        gtk.Window.setDefaultSize(win, w, h);
        gtk.Window.present(win);
        return window.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Box")) {
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else true;
        const orientation: gtk.Orientation = if (vertical) .vertical else .horizontal;
        const spacing: c_int = @intCast(propInt(props, "spacing") orelse 0);
        const box = gtk.Box.new(orientation, spacing);
        return box.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Label")) {
        const text = propStr(props, "text") orelse "";
        const label = gtk.Label.new(dupeZ(text));
        // GtkLabel defaults to centered text when it is allocated extra width.
        // Native form rows expect their expanding title labels to stay leading-aligned.
        gtk.Label.setXalign(label, 0.0);
        return label.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Button")) {
        const lbl = propStr(props, "label") orelse "Button";
        var button: *gtk.Button = undefined;
        if (propStr(props, "iconName")) |icon| {
            if (lbl.len == 0) {
                button = gtk.Button.new();
                gtk.Button.setIconName(button, dupeZ(icon));
            } else {
                button = gtk.Button.new();
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, dupeZ(icon));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                gtk.Button.setChild(button, content.as(gtk.Widget));
            }
        } else {
            button = gtk.Button.newWithLabel(dupeZ(lbl));
        }
        const label_align = propStr(props, "labelAlign") orelse "center";
        if (!std.mem.eql(u8, label_align, "center")) {
            if (gtk.Button.getChild(button)) |child| {
                const halign: gtk.Align = if (std.mem.eql(u8, label_align, "start")) .start else .end;
                gtk.Widget.setHalign(child, halign);
                if (gobject.ext.isA(child, gtk.Label)) {
                    const xalign: f32 = if (std.mem.eql(u8, label_align, "start")) 0.0 else 1.0;
                    gtk.Label.setXalign(@ptrCast(@alignCast(child)), xalign);
                }
            }
        }
        return button.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Terminal")) {
        const command: ?[*:0]const u8 = if (propStr(props, "command")) |c| dupeZ(c).ptr else null;
        const cwd: ?[*:0]const u8 = if (propStr(props, "cwd")) |c| dupeZ(c).ptr else null;
        const font_size: c_int = @intCast(propInt(props, "fontSize") orelse 13);
        const cols: u16 = @intCast(propInt(props, "cols") orelse 80);
        const rows: u16 = @intCast(propInt(props, "rows") orelse 24);
        return ndterm_gtk.create(command, cwd, font_size, cols, rows);
    } else if (std.mem.eql(u8, kind, "TextInput")) {
        const entry = gtk.Entry.new();
        const editable = entry.as(gtk.Editable);
        if (propStr(props, "text")) |t| { if (t.len > 0) gtk.Editable.setText(editable, dupeZ(t)); }
        if (propStr(props, "placeholder")) |p| gtk.Entry.setPlaceholderText(entry, dupeZ(p));
        if (propBool(props, "editable")) |e| gtk.Editable.setEditable(editable, @intFromBool(e));
        return entry.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "TextArea")) {
        const view = gtk.TextView.new();
        const buf = gtk.TextView.getBuffer(view);
        if (propStr(props, "text")) |t| { if (t.len > 0) gtk.TextBuffer.setText(buf, dupeZ(t), -1); }
        if (propInt(props, "minContentHeight")) |h| { if (h > 0) gtk.Widget.setSizeRequest(view.as(gtk.Widget), -1, @intCast(h)); }
        return view.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Checkbox")) {
        const cb = gtk.CheckButton.newWithLabel(dupeZ(propStr(props, "label") orelse ""));
        if (propBool(props, "checked") orelse false) gtk.CheckButton.setActive(cb, 1);
        return cb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Radio")) {
        const cb = gtk.CheckButton.newWithLabel(dupeZ(propStr(props, "label") orelse ""));
        if (propStr(props, "group")) |g| {
            std.debug.assert(events_ready); // initEvents runs before any create (runtime.zig startup order)
            if (radio_groups.get(g)) |first| {
                gtk.CheckButton.setGroup(cb, first);
            } else if (events_gpa.dupe(u8, g)) |key| {
                radio_groups.put(events_gpa, key, cb) catch events_gpa.free(key);
                // Evict the entry when this anchor dies (see cbRadioGroupDestroyed).
                _ = gtk.Widget.signals.destroy.connect(cb.as(gtk.Widget), ?*anyopaque, &cbRadioGroupDestroyed, null, .{});
            } else |_| {} // OOM: skip anchoring; this radio forms its own group
        } else {
            std.debug.print("ND_WARN Radio without group prop\n", .{});
        }
        if (propBool(props, "checked") orelse false) gtk.CheckButton.setActive(cb, 1);
        return cb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Select")) {
        const sl = gtk.StringList.new(null);
        if (propArray(props, "options")) |arr| {
            for (arr.items) |item| {
                if (item == .string) gtk.StringList.append(sl, dupeZ(item.string));
            }
        }
        const dd = gtk.DropDown.new(sl.as(gio.ListModel), null); // transfer-full: DropDown owns the model
        const idx = propInt(props, "selectedIndex") orelse 0;
        if (idx > 0) gtk.DropDown.setSelected(dd, @intCast(idx));
        return dd.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Slider")) {
        const min = propFloat(props, "min") orelse 0;
        const max = propFloat(props, "max") orelse 100;
        const step = propFloat(props, "step") orelse 1;
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else false;
        const scale = gtk.Scale.newWithRange(if (vertical) .vertical else .horizontal, min, max, step);
        gtk.Range.setValue(scale.as(gtk.Range), propFloat(props, "value") orelse 0);
        return scale.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ProgressBar")) {
        const pb = gtk.ProgressBar.new();
        if (propFloat(props, "fraction")) |f| gtk.ProgressBar.setFraction(pb, f);
        return pb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Image")) {
        const img = gtk.Image.new();
        if (propStr(props, "path")) |p| {
            gtk.Image.setFromFile(img, dupeZ(p));
        } else if (propStr(props, "iconName")) |n| {
            gtk.Image.setFromIconName(img, dupeZ(n));
        }
        return img.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ScrollView")) {
        const sw = gtk.ScrolledWindow.new();
        if (propInt(props, "minContentHeight")) |h| { if (h > 0) gtk.ScrolledWindow.setMinContentHeight(sw, @intCast(h)); }
        return sw.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Separator")) {
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else false;
        const sep = gtk.Separator.new(if (vertical) .vertical else .horizontal);
        return sep.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Spinner")) {
        const sp = gtk.Spinner.new();
        if (propBool(props, "spinning") orelse true) gtk.Spinner.setSpinning(sp, 1);
        return sp.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "TabView")) {
        // selectedIndex is ignored at create: pages attach afterwards (M5b-D4).
        const nb = gtk.Notebook.new();
        return nb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Grid")) {
        const grid = gtk.Grid.new();
        return grid.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ListView")) {
        const strv = buildStrv(propArray(props, "items"), dupeZ); // O(n) bulk build, not per-item append
        defer std.heap.page_allocator.free(strv);
        const model = gtk.StringList.new(@ptrCast(strv.ptr));
        const selection = gtk.SingleSelection.new(model.as(gio.ListModel)); // transfer-full: selection owns model
        const sel_idx = propInt(props, "selectedIndex") orelse -1;
        if (sel_idx >= 0) gtk.SingleSelection.setSelected(selection, @intCast(sel_idx));
        const factory = gtk.SignalListItemFactory.new();
        _ = gobject.signalConnectData(asObject(factory), "setup", @ptrCast(&lvSetup), null, null, .{});
        _ = gobject.signalConnectData(asObject(factory), "bind", @ptrCast(&lvBind), null, null, .{});
        const list = gtk.ListView.new(selection.as(gtk.SelectionModel), factory.as(gtk.ListItemFactory)); // transfer-full: list owns selection+factory
        const sw = gtk.ScrolledWindow.new(); // M5c-D3: ListView needs a scroller
        gtk.ScrolledWindow.setChild(sw, list.as(gtk.Widget));
        return sw.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "WebView")) {
        // Real WebKitGTK surface when libwebkitgtk-6.0 is dlopen-able at
        // runtime; placeholder label otherwise (M5b-D7: no hard link dep).
        const url: ?[*:0]const u8 = if (propStr(props, "url")) |u| dupeZ(u).ptr else null;
        return ndweb_gtk.create(url);
    } else if (std.mem.eql(u8, kind, "NativeView")) {
        const view_kind = propStr(props, "viewKind") orelse "";
        const props_json = propStr(props, "props") orelse "{}";
        if (nd_plugin.viewCreate(view_kind, props_json)) |v| {
            const nv: *gtk.Widget = @ptrCast(@alignCast(v));
            gobject.Object.setData(asObject(nv), "nd-view-kind", @ptrCast(@constCast(dupeZ(view_kind).ptr)));
            return nv;
        }
        std.debug.print("ND_WARN nativeView: no module registered viewKind={s}; rendering empty box\n", .{view_kind});
        return gtk.Box.new(.vertical, 0).as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SplitView")) {
        const sv = adw.OverlaySplitView.new();
        if (propFloat(props, "sidebarWidth")) |sw| { if (sw > 0) adw.OverlaySplitView.setSidebarWidthFraction(sv, sw); }
        if (propBool(props, "collapsed")) |c| adw.OverlaySplitView.setCollapsed(sv, @intFromBool(c));
        if (propFloat(props, "listWidth")) |lw| { if (lw > 0) split_list_widths.put(events_gpa, @intFromPtr(sv), lw) catch {}; }
        return sv.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "HeaderBar")) {
        const hb = adw.HeaderBar.new();
        if (propStr(props, "title")) |t| {
            if (t.len > 0) {
                const wt = adw.WindowTitle.new(dupeZ(t), "");
                adw.HeaderBar.setTitleWidget(hb, wt.as(gtk.Widget));
            }
        }
        ndMenuNoteHeaderBar(hb); // M13: track for primary-menu-button placement (no-op sans <menubar>)
        ndHeaderBarApplyNav(hb, propBool(props, "canGoBack"), propBool(props, "canGoForward"));
        return hb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ToolbarView")) {
        const tv = adw.ToolbarView.new();
        return tv.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SearchInput")) {
        const search = gtk.SearchEntry.new();
        const editable = search.as(gtk.Editable);
        if (propStr(props, "text")) |t| { if (t.len > 0) gtk.Editable.setText(editable, dupeZ(t)); }
        if (propStr(props, "placeholder")) |p| gtk.SearchEntry.setPlaceholderText(search, dupeZ(p));
        return search.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SourceList")) {
        const box = gtk.ListBox.new();
        gtk.ListBox.setSelectionMode(box, .browse);
        gtk.ListBox.setActivateOnSingleClick(box, 0);
        gtk.Widget.addCssClass(box.as(gtk.Widget), "navigation-sidebar");
        ndBuildSourceRows(box, propArray(props, "items"), dupeZ);
        const sel_idx = propInt(props, "selectedIndex") orelse -1;
        if (sel_idx >= 0) { if (gtk.ListBox.getRowAtIndex(box, @intCast(sel_idx))) |r| gtk.ListBox.selectRow(box, r); }
        const sw = gtk.ScrolledWindow.new();
        gtk.ScrolledWindow.setChild(sw, box.as(gtk.Widget));
        return sw.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Menubar")) {
        const defaults = propBool(props, "defaults") orelse true;
        return ndMenubarCreate(app, the_window.*, defaults);
    } else if (std.mem.eql(u8, kind, "Menu")) {
        const label = dupeZ(propStr(props, "label") orelse "");
        return ndMenuCreate(app, label);
    } else if (std.mem.eql(u8, kind, "MenuItem")) {
        return ndMenuItemCreate(app, props, dupeZ);
    } else if (std.mem.eql(u8, kind, "SettingsGroup")) {
        const spacing: c_int = @intCast(propInt(props, "spacing") orelse 0);
        const box = gtk.Box.new(.vertical, spacing);
        gtk.Widget.addCssClass(box.as(gtk.Widget), "card");
        return box.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Switch")) {
        const sw = gtk.Switch.new();
        gtk.Switch.setActive(sw, @intFromBool(propBool(props, "checked") orelse false));
        return sw.as(gtk.Widget);
    }
    std.debug.print("ND_WARN unknown widget kind={s}\n", .{kind});
    return error.UnknownWidget;
}

/// The GTK update dispatcher for createAndUpdate props.
pub fn applyProps(widget: *gtk.Widget, kind: []const u8, props: ?std.json.Value, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    if (std.mem.eql(u8, kind, "Window")) {
        if (propStr(props, "title")) |t| {
            const win: *gtk.Window = @ptrCast(@alignCast(widget));
            gtk.Window.setTitle(win, dupeZ(t));
        }
    } else if (std.mem.eql(u8, kind, "Box")) {
        if (propInt(props, "spacing")) |s| {
            const box: *gtk.Box = @ptrCast(@alignCast(widget));
            gtk.Box.setSpacing(box, @intCast(s));
        }
    } else if (std.mem.eql(u8, kind, "TextInput")) {
        if (propStr(props, "text")) |t| {
            const editable = @as(*gtk.Entry, @ptrCast(@alignCast(widget))).as(gtk.Editable);
            const cur = std.mem.span(gtk.Editable.getText(editable));
            if (!std.mem.eql(u8, cur, t)) {
                blockEcho(asObject(widget));
                gtk.Editable.setText(editable, dupeZ(t));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "placeholder")) |p_| gtk.Entry.setPlaceholderText(@ptrCast(@alignCast(widget)), dupeZ(p_));
        if (propBool(props, "editable")) |e| gtk.Editable.setEditable(@as(*gtk.Entry, @ptrCast(@alignCast(widget))).as(gtk.Editable), @intFromBool(e));
    } else if (std.mem.eql(u8, kind, "TextArea")) {
        if (propStr(props, "text")) |t| {
            const view: *gtk.TextView = @ptrCast(@alignCast(widget));
            const buf = gtk.TextView.getBuffer(view);
            var s_it: gtk.TextIter = undefined;
            var e_it: gtk.TextIter = undefined;
            gtk.TextBuffer.getStartIter(buf, &s_it);
            gtk.TextBuffer.getEndIter(buf, &e_it);
            const cur = gtk.TextBuffer.getText(buf, &s_it, &e_it, 0);
            defer glib.free(@ptrCast(cur));
            if (!std.mem.eql(u8, std.mem.span(cur), t)) {
                blockEcho(asObject(buf));
                gtk.TextBuffer.setText(buf, dupeZ(t), -1);
                unblockEcho(asObject(buf));
            }
        }
    } else if (std.mem.eql(u8, kind, "Checkbox")) {
        if (propBool(props, "checked")) |c| {
            const cb: *gtk.CheckButton = @ptrCast(@alignCast(widget));
            if ((gtk.CheckButton.getActive(cb) != 0) != c) {
                blockEcho(asObject(widget));
                gtk.CheckButton.setActive(cb, @intFromBool(c));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "label")) |l| gtk.CheckButton.setLabel(@ptrCast(@alignCast(widget)), dupeZ(l));
    } else if (std.mem.eql(u8, kind, "Radio")) {
        if (propBool(props, "checked")) |c| {
            const cb: *gtk.CheckButton = @ptrCast(@alignCast(widget));
            if ((gtk.CheckButton.getActive(cb) != 0) != c) {
                blockEcho(asObject(widget));
                gtk.CheckButton.setActive(cb, @intFromBool(c));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "label")) |l| gtk.CheckButton.setLabel(@ptrCast(@alignCast(widget)), dupeZ(l));
    } else if (std.mem.eql(u8, kind, "Select")) {
        if (propInt(props, "selectedIndex")) |idx| {
            const dd: *gtk.DropDown = @ptrCast(@alignCast(widget));
            if (gtk.DropDown.getSelected(dd) != @as(c_uint, @intCast(idx))) {
                blockEcho(asObject(widget));
                gtk.DropDown.setSelected(dd, @intCast(idx));
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "Slider")) {
        if (propFloat(props, "value")) |v| {
            const range = @as(*gtk.Scale, @ptrCast(@alignCast(widget))).as(gtk.Range);
            if (@abs(gtk.Range.getValue(range) - v) > 1e-9) {
                blockEcho(asObject(widget));
                gtk.Range.setValue(range, v);
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "ProgressBar")) {
        if (propFloat(props, "fraction")) |f| gtk.ProgressBar.setFraction(@ptrCast(@alignCast(widget)), f);
    } else if (std.mem.eql(u8, kind, "Image")) {
        if (propStr(props, "path")) |p_| gtk.Image.setFromFile(@ptrCast(@alignCast(widget)), dupeZ(p_));
        if (propStr(props, "iconName")) |n| gtk.Image.setFromIconName(@ptrCast(@alignCast(widget)), dupeZ(n));
    } else if (std.mem.eql(u8, kind, "Spinner")) {
        if (propBool(props, "spinning")) |sp| gtk.Spinner.setSpinning(@ptrCast(@alignCast(widget)), @intFromBool(sp));
    } else if (std.mem.eql(u8, kind, "TabView")) {
        if (propInt(props, "selectedIndex")) |idx| gtk.Notebook.setCurrentPage(@ptrCast(@alignCast(widget)), @intCast(idx));
    } else if (std.mem.eql(u8, kind, "ListView")) {
        {
            const sw: *gtk.ScrolledWindow = @ptrCast(@alignCast(widget));
            const list: *gtk.ListView = @ptrCast(@alignCast(gtk.ScrolledWindow.getChild(sw).?));
            const selection: *gtk.SingleSelection = @ptrCast(@alignCast(gtk.ListView.getModel(list).?));
            const model: *gtk.StringList = @ptrCast(@alignCast(gtk.SingleSelection.getModel(selection).?));
            const n_old = gio.ListModel.getNItems(model.as(gio.ListModel));
            const strv = buildStrv(propArray(props, "items"), dupeZ); // O(n) bulk build, not per-item append
            defer std.heap.page_allocator.free(strv);
            gtk.StringList.splice(model, 0, n_old, @ptrCast(strv.ptr)); // one call: replace-all
        }
        if (propInt(props, "selectedIndex")) |idx| {
            const sw: *gtk.ScrolledWindow = @ptrCast(@alignCast(widget));
            const list: *gtk.ListView = @ptrCast(@alignCast(gtk.ScrolledWindow.getChild(sw).?));
            const selection: *gtk.SingleSelection = @ptrCast(@alignCast(gtk.ListView.getModel(list).?));
            if (idx >= 0) gtk.SingleSelection.setSelected(selection, @intCast(idx));
        }
    } else if (std.mem.eql(u8, kind, "WebView")) {
        if (propStr(props, "url")) |u| ndweb_gtk.setUrl(widget, dupeZ(u));
    } else if (std.mem.eql(u8, kind, "NativeView")) {
        if (propStr(props, "props")) |pj| {
            if (gobject.Object.getData(asObject(widget), "nd-view-kind")) |raw| {
                nd_plugin.viewApplyProps(std.mem.span(@as([*:0]const u8, @ptrCast(raw))), widget, pj);
            }
        }
    } else if (std.mem.eql(u8, kind, "SplitView")) {
        if (propBool(props, "collapsed")) |c| adw.OverlaySplitView.setCollapsed(@ptrCast(@alignCast(widget)), @intFromBool(c));
    } else if (std.mem.eql(u8, kind, "HeaderBar")) {
        ndHeaderBarApplyNav(@ptrCast(@alignCast(widget)), propBool(props, "canGoBack"), null);
        ndHeaderBarApplyNav(@ptrCast(@alignCast(widget)), null, propBool(props, "canGoForward"));
    } else if (std.mem.eql(u8, kind, "SearchInput")) {
        if (propStr(props, "text")) |t| {
            const editable = @as(*gtk.SearchEntry, @ptrCast(@alignCast(widget))).as(gtk.Editable);
            const cur = std.mem.span(gtk.Editable.getText(editable));
            if (!std.mem.eql(u8, cur, t)) {
                blockEcho(asObject(widget));
                gtk.Editable.setText(editable, dupeZ(t));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "placeholder")) |p_| gtk.SearchEntry.setPlaceholderText(@ptrCast(@alignCast(widget)), dupeZ(p_));
    } else if (std.mem.eql(u8, kind, "SourceList")) {
        {
            const box: *gtk.ListBox = @ptrCast(@alignCast(scrolledWindowInner(@ptrCast(@alignCast(widget))).?));
            const prev = gtk.ListBox.getSelectedRow(box);
            const prev_idx: c_int = if (prev) |r| gtk.ListBoxRow.getIndex(r) else -1;
            blockEcho(asObject(box));
            gtk.ListBox.removeAll(box);
            ndBuildSourceRows(box, propArray(props, "items"), dupeZ);
            if (prev_idx >= 0) {
                if (gtk.ListBox.getRowAtIndex(box, prev_idx)) |r| gtk.ListBox.selectRow(box, r);
            }
            unblockEcho(asObject(box));
        }
        if (propInt(props, "selectedIndex")) |idx| {
            const box: *gtk.ListBox = @ptrCast(@alignCast(scrolledWindowInner(@ptrCast(@alignCast(widget))).?));
            const cur = gtk.ListBox.getSelectedRow(box);
            const cur_idx: i64 = if (cur) |r| gtk.ListBoxRow.getIndex(r) else -1;
            if (cur_idx != idx) {
                blockEcho(asObject(box));
                if (idx >= 0) {
                    if (gtk.ListBox.getRowAtIndex(box, @intCast(idx))) |r| gtk.ListBox.selectRow(box, r);
                } else gtk.ListBox.unselectAll(box);
                unblockEcho(asObject(box));
            }
        }
    } else if (std.mem.eql(u8, kind, "MenuItem")) {
        if (propBool(props, "enabled")) |en| ndMenuItemSetEnabled(widget, en);
    } else if (std.mem.eql(u8, kind, "SettingsGroup")) {
        if (propInt(props, "spacing")) |s| {
            const box: *gtk.Box = @ptrCast(@alignCast(widget));
            gtk.Box.setSpacing(box, @intCast(s));
        }
    } else if (std.mem.eql(u8, kind, "Switch")) {
        if (propBool(props, "checked")) |c| {
            const sw: *gtk.Switch = @ptrCast(@alignCast(widget));
            if ((gtk.Switch.getActive(sw) != 0) != c) {
                blockEcho(asObject(widget));
                gtk.Switch.setActive(sw, @intFromBool(c));
                unblockEcho(asObject(widget));
            }
        }
    }
}

fn lvSetup(_: *gobject.Object, list_item: *gtk.ListItem, _: ?*anyopaque) callconv(.c) void {
    const label = gtk.Label.new(null);
    gtk.ListItem.setChild(list_item, label.as(gtk.Widget));
}
fn lvBind(_: *gobject.Object, list_item: *gtk.ListItem, _: ?*anyopaque) callconv(.c) void {
    const child = gtk.ListItem.getChild(list_item) orelse return;
    const label: *gtk.Label = @ptrCast(@alignCast(child));
    const obj = gtk.ListItem.getItem(list_item) orelse return;
    const so: *gtk.StringObject = @ptrCast(@alignCast(obj));
    gtk.Label.setText(label, gtk.StringObject.getString(so));
}

fn cbClicked(_: *gobject.Object, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "clicked", .{});
}

fn cbEditableChanged(obj: *gobject.Object, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const editable: *gtk.Editable = @ptrCast(@alignCast(obj));
    const text = std.mem.span(gtk.Editable.getText(editable));
    if (emit) |f| f(node_id, "changed", .{ .text = text });
}

fn cbEntryActivate(obj: *gobject.Object, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const editable: *gtk.Editable = @ptrCast(@alignCast(obj));
    const text = std.mem.span(gtk.Editable.getText(editable));
    if (emit) |f| f(node_id, "activate", .{ .text = text });
}

fn cbBufferChanged(obj: *gobject.Object, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const buf: *gtk.TextBuffer = @ptrCast(@alignCast(obj));
    var s_it: gtk.TextIter = undefined;
    var e_it: gtk.TextIter = undefined;
    gtk.TextBuffer.getStartIter(buf, &s_it);
    gtk.TextBuffer.getEndIter(buf, &e_it);
    const ctext = gtk.TextBuffer.getText(buf, &s_it, &e_it, 0);
    defer glib.free(@ptrCast(ctext));
    if (emit) |f| f(node_id, "changed", .{ .text = std.mem.span(ctext) });
}

fn cbCheckToggled(obj: *gobject.Object, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const cb: *gtk.CheckButton = @ptrCast(@alignCast(obj));
    if (emit) |f| f(node_id, "toggled", .{ .checked = gtk.CheckButton.getActive(cb) != 0 });
}

// notify:: handlers get (object, pspec, user_data).
fn cbDropDownSelected(obj: *gobject.Object, _: ?*anyopaque, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const dd: *gtk.DropDown = @ptrCast(@alignCast(obj));
    const sel = gtk.DropDown.getSelected(dd);
    if (sel == std.math.maxInt(c_uint)) return; // GTK_INVALID_LIST_POSITION
    if (emit) |f| f(node_id, "selectionChanged", .{ .index = @intCast(sel) });
}

fn cbScaleValueChanged(obj: *gobject.Object, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const range: *gtk.Range = @ptrCast(@alignCast(obj));
    if (emit) |f| f(node_id, "valueChanged", .{ .value = gtk.Range.getValue(range) });
}

// the ListView `activate` signal passes (list_view, position, user_data).
fn cbListActivate(obj: *gobject.Object, position: c_uint, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    _ = obj;
    if (emit) |f| f(node_id, "rowActivated", .{ .index = @intCast(position) });
}

fn cbListBoxRowSelected(_: *gobject.Object, row: ?*gtk.ListBoxRow, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const idx: i64 = if (row) |r| gtk.ListBoxRow.getIndex(r) else -1;
    if (emit) |f| f(node_id, "selectionChanged", .{ .index = idx });
}

fn cbListBoxRowActivated(_: *gobject.Object, row: *gtk.ListBoxRow, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "rowActivated", .{ .index = gtk.ListBoxRow.getIndex(row) });
}

// notify:: handlers get (object, pspec, user_data).
fn cbSwitchToggled(obj: *gobject.Object, _: ?*anyopaque, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const sw: *gtk.Switch = @ptrCast(@alignCast(obj));
    if (emit) |f| f(node_id, "toggled", .{ .checked = gtk.Switch.getActive(sw) != 0 });
}

pub fn connectEvents(widget: *gtk.Widget, kind: []const u8, node_id: u32) void {
    const data: ?*anyopaque = @ptrFromInt(@as(usize, node_id));
    if (std.mem.eql(u8, kind, "Button")) {
        const obj_Button_clicked = asObject(widget);
        const hid_Button_clicked = gobject.signalConnectData(obj_Button_clicked, "clicked", @ptrCast(&cbClicked), data, null, .{});
        _ = hid_Button_clicked;
    } else if (std.mem.eql(u8, kind, "TextInput")) {
        const obj_TextInput_changed = asObject(widget);
        const hid_TextInput_changed = gobject.signalConnectData(obj_TextInput_changed, "changed", @ptrCast(&cbEditableChanged), data, null, .{});
        noteSuppressible(obj_TextInput_changed, hid_TextInput_changed);
        const obj_TextInput_activate = asObject(widget);
        const hid_TextInput_activate = gobject.signalConnectData(obj_TextInput_activate, "activate", @ptrCast(&cbEntryActivate), data, null, .{});
        _ = hid_TextInput_activate;
    } else if (std.mem.eql(u8, kind, "TextArea")) {
        const obj_TextArea_changed = asObject(gtk.TextView.getBuffer(@ptrCast(@alignCast(widget))));
        const hid_TextArea_changed = gobject.signalConnectData(obj_TextArea_changed, "changed", @ptrCast(&cbBufferChanged), data, null, .{});
        noteSuppressible(obj_TextArea_changed, hid_TextArea_changed);
    } else if (std.mem.eql(u8, kind, "Checkbox")) {
        const obj_Checkbox_toggled = asObject(widget);
        const hid_Checkbox_toggled = gobject.signalConnectData(obj_Checkbox_toggled, "toggled", @ptrCast(&cbCheckToggled), data, null, .{});
        noteSuppressible(obj_Checkbox_toggled, hid_Checkbox_toggled);
    } else if (std.mem.eql(u8, kind, "Radio")) {
        const obj_Radio_toggled = asObject(widget);
        const hid_Radio_toggled = gobject.signalConnectData(obj_Radio_toggled, "toggled", @ptrCast(&cbCheckToggled), data, null, .{});
        noteSuppressible(obj_Radio_toggled, hid_Radio_toggled);
    } else if (std.mem.eql(u8, kind, "Select")) {
        const obj_Select_selectionChanged = asObject(widget);
        const hid_Select_selectionChanged = gobject.signalConnectData(obj_Select_selectionChanged, "notify::selected", @ptrCast(&cbDropDownSelected), data, null, .{});
        noteSuppressible(obj_Select_selectionChanged, hid_Select_selectionChanged);
    } else if (std.mem.eql(u8, kind, "Slider")) {
        const obj_Slider_valueChanged = asObject(widget);
        const hid_Slider_valueChanged = gobject.signalConnectData(obj_Slider_valueChanged, "value-changed", @ptrCast(&cbScaleValueChanged), data, null, .{});
        noteSuppressible(obj_Slider_valueChanged, hid_Slider_valueChanged);
    } else if (std.mem.eql(u8, kind, "ListView")) {
        const obj_ListView_rowActivated = asObject(scrolledWindowInner(@ptrCast(@alignCast(widget))).?);
        const hid_ListView_rowActivated = gobject.signalConnectData(obj_ListView_rowActivated, "activate", @ptrCast(&cbListActivate), data, null, .{});
        _ = hid_ListView_rowActivated;
    } else if (std.mem.eql(u8, kind, "WebView")) {
        if (emit) |f| ndweb_gtk.connectEvents(widget, node_id, f);
    } else if (std.mem.eql(u8, kind, "NativeView")) {
    } else if (std.mem.eql(u8, kind, "HeaderBar")) {
        ndHeaderBarConnectNav(widget, node_id);
    } else if (std.mem.eql(u8, kind, "SearchInput")) {
        const obj_SearchInput_changed = asObject(widget);
        const hid_SearchInput_changed = gobject.signalConnectData(obj_SearchInput_changed, "search-changed", @ptrCast(&cbEditableChanged), data, null, .{});
        noteSuppressible(obj_SearchInput_changed, hid_SearchInput_changed);
        const obj_SearchInput_activate = asObject(widget);
        const hid_SearchInput_activate = gobject.signalConnectData(obj_SearchInput_activate, "activate", @ptrCast(&cbEntryActivate), data, null, .{});
        _ = hid_SearchInput_activate;
    } else if (std.mem.eql(u8, kind, "SourceList")) {
        const obj_SourceList_selectionChanged = asObject(scrolledWindowInner(@ptrCast(@alignCast(widget))).?);
        const hid_SourceList_selectionChanged = gobject.signalConnectData(obj_SourceList_selectionChanged, "row-selected", @ptrCast(&cbListBoxRowSelected), data, null, .{});
        noteSuppressible(obj_SourceList_selectionChanged, hid_SourceList_selectionChanged);
        const obj_SourceList_rowActivated = asObject(scrolledWindowInner(@ptrCast(@alignCast(widget))).?);
        const hid_SourceList_rowActivated = gobject.signalConnectData(obj_SourceList_rowActivated, "row-activated", @ptrCast(&cbListBoxRowActivated), data, null, .{});
        _ = hid_SourceList_rowActivated;
    } else if (std.mem.eql(u8, kind, "MenuItem")) {
        ndMenuItemConnect(widget, node_id); // M13: GSimpleAction wiring, not a GtkWidget signal
    } else if (std.mem.eql(u8, kind, "Switch")) {
        const obj_Switch_toggled = asObject(widget);
        const hid_Switch_toggled = gobject.signalConnectData(obj_Switch_toggled, "notify::active", @ptrCast(&cbSwitchToggled), data, null, .{});
        noteSuppressible(obj_Switch_toggled, hid_Switch_toggled);
    }
}

/// App -> widget imperative commands (widgetCommand NDP frame, M14).
pub fn widgetCommand(widget: *gtk.Widget, kind: []const u8, command: []const u8, arg: ?std.json.Value) void {
    if (std.mem.eql(u8, kind, "WebView")) {
        ndweb_gtk.command(widget, command, arg);
    } else {
        std.debug.print("ND_WARN widgetCommand on kind={s} with no commands\n", .{kind});
    }
}

pub fn appendChild(parent: *gtk.Widget, parent_kind: []const u8, child: *gtk.Widget, attached: protocol.Attached, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    if (std.mem.eql(u8, parent_kind, "Window")) {
        if (!gobject.ext.isA(child, gtk.Widget)) {
            ndMenuAttachToWindow(child);
        } else adw.ApplicationWindow.setContent(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "Box")) {
        const box: *gtk.Box = @ptrCast(@alignCast(parent));
        if (gtk.Widget.getParent(child) != null) {
            // Moving an already-mounted child to the end (e.g. `insertBefore`
            // degenerating here because `before` was null — see insertBefore
            // below): `gtk_box_append` asserts the child has no parent, same
            // constraint as `insertChildAfter`. `reorderChildAfter` anchored
            // on the current last child is GTK's move-to-end primitive.
            gtk.Box.reorderChildAfter(box, child, gtk.Widget.getLastChild(parent));
        } else {
            gtk.Box.append(box, child);
        }
    } else if (std.mem.eql(u8, parent_kind, "ScrollView")) {
        gtk.ScrolledWindow.setChild(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "TabView")) {
        const nb: *gtk.Notebook = @ptrCast(@alignCast(parent));
        _ = gtk.Notebook.appendPage(nb, child, null);
        if (attached.tab_label) |tl| gtk.Notebook.setTabLabelText(nb, child, dupeZ(tl));
    } else if (std.mem.eql(u8, parent_kind, "Grid")) {
        gtk.Grid.attach(@ptrCast(@alignCast(parent)), child, @intCast(attached.grid_column), @intCast(attached.grid_row), @intCast(attached.grid_column_span), @intCast(attached.grid_row_span));
    } else if (std.mem.eql(u8, parent_kind, "SplitView")) {
        const sv: *adw.OverlaySplitView = @ptrCast(@alignCast(parent));
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "sidebar")) {
                adw.OverlaySplitView.setSidebar(sv, child);
            } else if (std.mem.eql(u8, sl, "list")) {
                adw.OverlaySplitView.setSidebar(ndSplitViewInner(sv), child);
            } else if (adw.OverlaySplitView.getContent(sv)) |cur| {
                if (gobject.ext.isA(cur, adw.OverlaySplitView)) adw.OverlaySplitView.setContent(@ptrCast(@alignCast(cur)), child)
                else adw.OverlaySplitView.setContent(sv, child);
            } else adw.OverlaySplitView.setContent(sv, child);
        } else adw.OverlaySplitView.setContent(sv, child);
    } else if (std.mem.eql(u8, parent_kind, "HeaderBar")) {
        const hb: *adw.HeaderBar = @ptrCast(@alignCast(parent));
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "end")) adw.HeaderBar.packEnd(hb, child)
            else adw.HeaderBar.packStart(hb, child);
        } else adw.HeaderBar.packStart(hb, child);
    } else if (std.mem.eql(u8, parent_kind, "ToolbarView")) {
        const tv: *adw.ToolbarView = @ptrCast(@alignCast(parent));
        if (gobject.ext.isA(child, adw.HeaderBar)) adw.ToolbarView.addTopBar(tv, child)
        else adw.ToolbarView.setContent(tv, child);
    } else if (std.mem.eql(u8, parent_kind, "Menubar")) {
        ndMenubarAppendMenu(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "Menu")) {
        ndMenuAppendItem(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "SettingsGroup")) {
        const box: *gtk.Box = @ptrCast(@alignCast(parent));
        if (gtk.Widget.getParent(child) != null) gtk.Box.reorderChildAfter(box, child, gtk.Widget.getLastChild(parent))
        else gtk.Box.append(box, child);
    } else {
        std.debug.print("ND_WARN append to non-container kind={s}\n", .{parent_kind});
    }
}

pub fn insertBefore(parent: *gtk.Widget, parent_kind: []const u8, child: *gtk.Widget, before: ?*gtk.Widget, attached: protocol.Attached, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    // null `before` degenerates to append everywhere (matches the M4 hand-written contract).
    const b = before orelse return appendChild(parent, parent_kind, child, attached, dupeZ);
    if (std.mem.eql(u8, parent_kind, "Box")) {
        const box: *gtk.Box = @ptrCast(@alignCast(parent));
        const prev = gtk.Widget.getPrevSibling(b);
        if (gtk.Widget.getParent(child) != null) {
            // Reordering an already-mounted child (e.g. a pin-sort), not a
            // fresh insert: `gtk_box_insert_child_after` asserts the child
            // has no parent and would silently no-op (Gtk-CRITICAL) here.
            // `reorderChildAfter` is GTK's dedicated move primitive — it
            // repositions the child in place with no unparent, so it can't
            // cascade-destroy the moved child's own children (the M8 GC
            // lesson: unparenting an interior node destroys its subtree).
            gtk.Box.reorderChildAfter(box, child, prev);
        } else {
            gtk.Box.insertChildAfter(box, child, prev);
        }
    } else if (std.mem.eql(u8, parent_kind, "TabView")) {
        const nb: *gtk.Notebook = @ptrCast(@alignCast(parent));
        const pos = gtk.Notebook.pageNum(nb, b);
        _ = gtk.Notebook.insertPage(nb, child, null, pos);
        if (attached.tab_label) |tl| gtk.Notebook.setTabLabelText(nb, child, dupeZ(tl));
    } else if (std.mem.eql(u8, parent_kind, "Grid")) {
        // Grid children are position-addressed; sibling order is irrelevant.
        gtk.Grid.attach(@ptrCast(@alignCast(parent)), child, @intCast(attached.grid_column), @intCast(attached.grid_row), @intCast(attached.grid_column_span), @intCast(attached.grid_row_span));
    } else if (std.mem.eql(u8, parent_kind, "SplitView")) {
        const sv: *adw.OverlaySplitView = @ptrCast(@alignCast(parent));
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "sidebar")) {
                adw.OverlaySplitView.setSidebar(sv, child);
            } else if (std.mem.eql(u8, sl, "list")) {
                adw.OverlaySplitView.setSidebar(ndSplitViewInner(sv), child);
            } else if (adw.OverlaySplitView.getContent(sv)) |cur| {
                if (gobject.ext.isA(cur, adw.OverlaySplitView)) adw.OverlaySplitView.setContent(@ptrCast(@alignCast(cur)), child)
                else adw.OverlaySplitView.setContent(sv, child);
            } else adw.OverlaySplitView.setContent(sv, child);
        } else adw.OverlaySplitView.setContent(sv, child);
    } else if (std.mem.eql(u8, parent_kind, "HeaderBar")) {
        const hb: *adw.HeaderBar = @ptrCast(@alignCast(parent));
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "end")) adw.HeaderBar.packEnd(hb, child)
            else adw.HeaderBar.packStart(hb, child);
        } else adw.HeaderBar.packStart(hb, child);
    } else if (std.mem.eql(u8, parent_kind, "SettingsGroup")) {
        const box: *gtk.Box = @ptrCast(@alignCast(parent));
        const prev = gtk.Widget.getPrevSibling(b);
        if (gtk.Widget.getParent(child) != null) gtk.Box.reorderChildAfter(box, child, prev)
        else gtk.Box.insertChildAfter(box, child, prev);
    } else {
        // single-child containers: insertBefore degenerates to appendChild.
        appendChild(parent, parent_kind, child, attached, dupeZ);
    }
}

pub fn removeChild(parent: *gtk.Widget, parent_kind: []const u8, child: *gtk.Widget) void {
    if (std.mem.eql(u8, parent_kind, "Window")) {
        if (gobject.ext.isA(child, gtk.Widget)) adw.ApplicationWindow.setContent(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "Box")) {
        gtk.Box.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "ScrollView")) {
        gtk.ScrolledWindow.setChild(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "TabView")) {
        const nb: *gtk.Notebook = @ptrCast(@alignCast(parent));
        const pos = gtk.Notebook.pageNum(nb, child);
        if (pos >= 0) gtk.Notebook.removePage(nb, pos);
    } else if (std.mem.eql(u8, parent_kind, "Grid")) {
        gtk.Grid.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "SplitView")) {
        const sv: *adw.OverlaySplitView = @ptrCast(@alignCast(parent));
        if (adw.OverlaySplitView.getSidebar(sv) == child) {
            adw.OverlaySplitView.setSidebar(sv, null);
        } else if (adw.OverlaySplitView.getContent(sv)) |cur| {
            if (cur == child) {
                adw.OverlaySplitView.setContent(sv, null);
            } else if (gobject.ext.isA(cur, adw.OverlaySplitView)) {
                const inner: *adw.OverlaySplitView = @ptrCast(@alignCast(cur));
                if (adw.OverlaySplitView.getSidebar(inner) == child) adw.OverlaySplitView.setSidebar(inner, null)
                else if (adw.OverlaySplitView.getContent(inner) == child) adw.OverlaySplitView.setContent(inner, null);
            }
        }
    } else if (std.mem.eql(u8, parent_kind, "HeaderBar")) {
        adw.HeaderBar.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "ToolbarView")) {
        adw.ToolbarView.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "Menubar")) {
        // M13: submenu removal rebuilds on next refresh (v1 no-op)
    } else if (std.mem.eql(u8, parent_kind, "Menu")) {
        // M13: item removal rebuilds on next refresh (v1 no-op)
    } else if (std.mem.eql(u8, parent_kind, "SettingsGroup")) {
        gtk.Box.remove(@ptrCast(@alignCast(parent)), child);
    } else {
        std.debug.print("ND_WARN remove from non-container kind={s}\n", .{parent_kind});
    }
}

pub const StyleTarget = enum { css, widget };
pub const StyleKeyDef = struct { name: []const u8, css: ?[]const u8, target: StyleTarget, kind: []const u8, unit: ?[]const u8 };
pub const style_keys = [_]StyleKeyDef{
    .{ .name = "background", .css = "background-color", .target = .css, .kind = "color", .unit = null },
